    /// <summary>Locates the files the generated code reads and writes at runtime.</summary>
    public static class RuntimeStorage
    {
        private static string? _folder;
        /// <summary>Per-user folder for this app's data (~/.local/share/App on Linux, %LOCALAPPDATA%\App on Windows) - created on first use.</summary>
        public static string Folder
        {
            get
            {
                if (_folder != null) return _folder;
                var name = typeof(DemoDataSet).Assembly.GetName().Name ?? "app";
                var root = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                if (root.Length == 0) root = Path.GetTempPath();
                var dir = Path.Combine(root, name);
                try { Directory.CreateDirectory(dir); } catch { /* the failing write reports it */ }
                _folder = dir;
                return dir;
            }
        }
        /// <summary>Absolute path of a runtime data file: the per-user copy when it exists, else a
        /// file of that name beside the executable (an earlier build wrote it there), else the
        /// per-user location - which the caller then creates.</summary>
        public static string PathFor(string name)
        {
            var user = Path.Combine(Folder, name);
            if (File.Exists(user)) return user;
            var beside = Path.Combine(AppContext.BaseDirectory, name);
            if (File.Exists(beside)) return beside;
            return user;
        }
    }

    /// <summary>Small SQLite helper shared by the tables the DataSet designer stores in a database file.</summary>
    public static class DatabaseAdapter
    {
        private static bool _ready;
        private static readonly object Sync = new();
        private static void EnsureReady()
        {
            lock (Sync) { if (_ready) return; _ready = true; global::SQLitePCL.Batteries_V2.Init(); }
        }
        /// <summary>Absolute path of a database file (relative paths resolve to the per-user data folder).</summary>
        public static string DbPath(string file) => Path.IsPathRooted(file) ? file : RuntimeStorage.PathFor(file);
        /// <summary>Opens the database (creating the file if needed) and runs an idempotent CREATE TABLE.</summary>
        public static Microsoft.Data.Sqlite.SqliteConnection Open(string file, string createSql)
        {
            EnsureReady();
            var con = new Microsoft.Data.Sqlite.SqliteConnection("Data Source=" + DbPath(file));
            con.Open();
            if (!string.IsNullOrEmpty(createSql)) { using var cmd = con.CreateCommand(); cmd.CommandText = createSql; cmd.ExecuteNonQuery(); }
            return con;
        }
        /// <summary>Brings an existing table in line with the designer schema: adds any columns
        /// the DataSet has but the DB table lacks (so 'add column → Generate Code' works on an
        /// existing file without losing its rows). New columns are added nullable.</summary>
        public static void EnsureColumns(Microsoft.Data.Sqlite.SqliteConnection con, string table, string[] cols)
        {
            var existing = new System.Collections.Generic.HashSet<string>(System.StringComparer.OrdinalIgnoreCase);
            using (var c = con.CreateCommand())
            {
                c.CommandText = $"PRAGMA table_info(\"{table}\")";
                using var rd = c.ExecuteReader();
                while (rd.Read()) existing.Add(rd.GetString(1));
            }
            foreach (var col in cols)
            {
                var name = col.Split(' ')[0];
                var affinity = col.Substring(name.Length).Trim();
                if (existing.Contains(name)) continue;
                using var a = con.CreateCommand();
                a.CommandText = $"ALTER TABLE \"{table}\" ADD COLUMN \"{name}\" {affinity}";
                a.ExecuteNonQuery();
            }
        }
    }

