    /// <summary>Remembers the folder the row dialogs' "Browse…" picker used last (best-effort).</summary>
    public static class FilePickerMemory
    {
        private static string? _folder;
        private static bool _loaded;
        private static string StorePath => RuntimeStorage.PathFor("DemoDataSet.lastfolder");
        /// <summary>The folder the last Browse… dialog used (null = let the OS pick its default).</summary>
        public static string? LastFolder
        {
            get
            {
                if (!_loaded)
                {
                    _loaded = true;
                    try { if (File.Exists(StorePath)) _folder = File.ReadAllText(StorePath).Trim(); } catch { /* best effort */ }
                }
                return _folder;
            }
            set
            {
                _loaded = true;
                _folder = value;
                try
                {
                    if (string.IsNullOrEmpty(value)) { if (File.Exists(StorePath)) File.Delete(StorePath); }
                    else File.WriteAllText(StorePath, value);
                }
                catch { /* best effort (read-only app folder) */ }
            }
        }
    }

    public class ImagesEditDialog : Window
    {
        private readonly System.Data.DataTable _table;
        private NumericUpDown idInput = null!;
        private TextBox imageInput = null!;
        private TextBox fileInput = null!;

        public ImagesEditDialog(System.Data.DataTable table, ImagesRow? row, int? newKey = null)
        {
            _table = table;
            Width = 360;
            Title = row == null ? "Add Images" : "Edit Images";
            var root = new StackPanel { Margin = new Thickness(12), Spacing = 8 };
        root.Children.Add(new TextBlock { Text = "ID" });
        idInput = new NumericUpDown { Minimum = 0, Increment = 1 };
        root.Children.Add(idInput);
        root.Children.Add(new TextBlock { Text = "Image" });
        imageInput = new TextBox();
        var row_imageInput = new Grid();
        row_imageInput.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Star));
        row_imageInput.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
        row_imageInput.Children.Add(imageInput);
        var browse_imageInput = new Button { Content = "Browse…" };
        browse_imageInput.Margin = new Thickness(6, 0, 0, 0);
        browse_imageInput.Click += async (_, _) => await BrowseAsync(imageInput);
        Grid.SetColumn(browse_imageInput, 1);
        row_imageInput.Children.Add(browse_imageInput);
        root.Children.Add(row_imageInput);
        root.Children.Add(new TextBlock { Text = "File" });
        fileInput = new TextBox();
        var row_fileInput = new Grid();
        row_fileInput.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Star));
        row_fileInput.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
        row_fileInput.Children.Add(fileInput);
        var browse_fileInput = new Button { Content = "Browse…" };
        browse_fileInput.Margin = new Thickness(6, 0, 0, 0);
        browse_fileInput.Click += async (_, _) => await BrowseAsync(fileInput);
        Grid.SetColumn(browse_fileInput, 1);
        row_fileInput.Children.Add(browse_fileInput);
        root.Children.Add(row_fileInput);
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8, HorizontalAlignment = HorizontalAlignment.Right };
            var saveBtn = new Button { Content = "Save", IsDefault = true };
            saveBtn.Click += (_, _) => Close(true);
            var cancelBtn = new Button { Content = "Cancel", IsCancel = true };
            cancelBtn.Click += (_, _) => Close();
            btnRow.Children.Add(saveBtn);
            btnRow.Children.Add(cancelBtn);
            root.Children.Add(btnRow);
            Content = root;
            if (row != null) LoadRow(row);
            else if (newKey.HasValue) { idInput.Value = newKey.Value; idInput.IsReadOnly = true; }
        }

        private void LoadRow(ImagesRow row)
        {
        idInput.Value = row.Id;
        imageInput.Text = row.Image;
        fileInput.Text = row.File;
        }

        public ImagesRow NewRow()
        {
            var row = new ImagesRow();
            ApplyTo(row);
            return row;
        }

        public void ApplyTo(ImagesRow row)
        {
        row.Id = (int)Math.Truncate(idInput.Value.GetValueOrDefault());
        row.Image = imageInput.Text;
        row.File = fileInput.Text;
        }

        private async Task BrowseAsync(TextBox box)
        {
            var options = new FilePickerOpenOptions
            {
                Title = "Select a file",
                AllowMultiple = false,
                FileTypeFilter = new[] { FilePickerFileTypes.ImageAll, FilePickerFileTypes.All }
            };
            var last = FilePickerMemory.LastFolder;
            if (!string.IsNullOrEmpty(last))
            {
                try { options.SuggestedStartLocation = await StorageProvider.TryGetFolderFromPathAsync(new Uri(last)); }
                catch { /* the remembered folder is gone - let the OS choose */ }
            }
            var files = await StorageProvider.OpenFilePickerAsync(options);
            if (files.Count == 0) return;
            var path = files[0].TryGetLocalPath();
            if (string.IsNullOrEmpty(path)) return;
            box.Text = path;
            try { FilePickerMemory.LastFolder = Path.GetDirectoryName(path); } catch { /* best effort */ }
        }
    }

    public class ConfirmDialog : Window
    {
        public ConfirmDialog(string title, string message)
        {
            Title = title;
            Width = 320;
            var root = new StackPanel { Margin = new Thickness(12), Spacing = 12 };
            root.Children.Add(new TextBlock { Text = message, TextWrapping = Avalonia.Media.TextWrapping.Wrap });
            var btnRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8, HorizontalAlignment = HorizontalAlignment.Right };
            var yesBtn = new Button { Content = "Yes", IsDefault = true };
            yesBtn.Click += (_, _) => Close(true);
            var noBtn = new Button { Content = "No", IsCancel = true };
            noBtn.Click += (_, _) => Close();
            btnRow.Children.Add(yesBtn);
            btnRow.Children.Add(noBtn);
            root.Children.Add(btnRow);
            Content = root;
        }
    }

    public class DateTimeToOffsetConverter : Avalonia.Data.Converters.IValueConverter
    {
        public object? Convert(object? value, Type targetType, object? parameter, System.Globalization.CultureInfo culture)
        {
            if (value is DateTime dt && dt != DateTime.MinValue) return new DateTimeOffset(DateTime.SpecifyKind(dt, DateTimeKind.Local));
            return null;
        }
        public object? ConvertBack(object? value, Type targetType, object? parameter, System.Globalization.CultureInfo culture)
        {
            if (value is DateTimeOffset dto) return dto.LocalDateTime;
            return null;
        }
    }
